def run(db):
    import ida_bytes, ida_funcs
    out = {}
    # 0x718d4d8/0x718d4e0 are in a vtable (data). Find which vtable and which functions live at those slots.
    # They are "handler" pointers - the vtable containing them is likely for a WT/QUIC connection.
    # Find the vtable start: search backwards for a symbol, and check the slot owners.
    for slot, label in [(0x718d4d8, "slotA"), (0x718d4e0, "slotB")]:
        # search backwards up to 0x200 for a known vtable signature (prev qwords are code ptrs)
        qs = []
        for i in range(0, 40):
            ea = slot - 8*i
            q = ida_bytes.get_qword(ea)
            qs.append((hex(ea), hex(q)))
        out[label+"_back"] = qs[:40]
    return out
`;
